import java.util.*;
import java.io.*;

public class Main {
    static final long MOD_A = 998244353L;
    static final long MOD_B = 1000000007L;

    static long getInput(BufferedReader br, StringTokenizer st) throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return 0;
            st = new StringTokenizer(line);
        }
        return Long.parseLong(st.nextToken());
    }

    static long n_value;
    static List<Integer>[] buckets = new ArrayList[10];
    static long[] prefix_sum = new long[10];
    static long counter1 = 0, counter2 = 0, total_ans = 0;
    static int[] powers = {1, 10, 100, 1000, 10000, 100000, 1000000};

    static void generate_combinations(int length, long value) {
        if (length > 6) return;
        buckets[length].add((int)((counter1 - value + MOD_A) % MOD_A));
        prefix_sum[length] += (counter1 - value + MOD_A) % MOD_A;
        ++counter1;
        for (int digit = 0; digit <= 9; ++digit) {
            generate_combinations(length + 1, value * 10 + digit);
        }
    }

    static boolean is_valid(long x) {
        return x * 1000000 + 999999 <= n_value && x * 10000000 > n_value;
    }

    static void explore(int length, long value) {
        if (value > n_value) return;
        if (is_valid(value)) {
            for (int i = 0; i <= 6; ++i) {
                long v1 = ((counter2 + 1 - value * powers[i]) % MOD_A + MOD_A) % MOD_A;
                int idx = lowerBound(buckets[i], (int)(MOD_A - v1));
                long sum = prefix_sum[i] + (long)buckets[i].size() * v1 - (long)MOD_A * (buckets[i].size() - idx);
                total_ans = (total_ans + sum) % MOD_B;
            }
            counter2 += counter1;
        } else {
            if (length > 0) ++counter2;
            long temp = ((counter2 - value) % MOD_A + MOD_A) % MOD_A;
            total_ans = (total_ans + temp) % MOD_B;
            for (int digit = (length == 0 ? 1 : 0); digit <= 9; ++digit) {
                explore(length + 1, value * 10 + digit);
            }
        }
    }

    static int lowerBound(List<Integer> list, int target) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= target) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = null;
        n_value = getInput(br, st);
        for (int i = 0; i <= 9; ++i) {
            buckets[i] = new ArrayList<>();
        }
        generate_combinations(0, 0);
        for (int i = 0; i <= 6; ++i) {
            Collections.sort(buckets[i]);
        }
        explore(0, 0);
        System.out.println(total_ans);
    }
}
